import java.util.*;

class Solution {
    public List<List<Integer>> shiftGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        k = k % total;
        int[][] res = new int[m][n];
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                int idx = i * n + j;
                int newIdx = (idx + k) % total;
                int ni = newIdx / n;
                int nj = newIdx % n;
                res[ni][nj] = grid[i][j];
            }
        }
        List<List<Integer>> ans = new ArrayList<>(m);
        for (int i = 0; i < m; ++i) {
            List<Integer> row = new ArrayList<>(n);
            for (int j = 0; j < n; ++j) row.add(res[i][j]);
            ans.add(row);
        }
        return ans;
    }
}

